-- composition of rule kernels join_order x redundant_order (duckdb), template not_exists
SELECT count(*) FROM (SELECT '0'::interval AS c0, '1999-12-31'::date AS c1, 0.0::float8 AS c2 FROM ti AS a1 WHERE (SELECT BOOL_OR (a2.c0) FROM (SELECT FALSE AS c0 ORDER BY ALL) AS a2)) AS ka WHERE NOT EXISTS (SELECT 1 FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 100) SELECT 0 AS c0 UNION SELECT 7 AS c0) AS kb);
-- pgfuzz:check kernel:not_exists SELECT CASE WHEN (SELECT count(*) FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 100) SELECT 0 AS c0 UNION SELECT 7 AS c0) AS kb) = 0 THEN (SELECT count(*) FROM (SELECT '0'::interval AS c0, '1999-12-31'::date AS c1, 0.0::float8 AS c2 FROM ti AS a1 WHERE (SELECT BOOL_OR (a2.c0) FROM (SELECT FALSE AS c0 ORDER BY ALL) AS a2)) AS ka) ELSE 0 END
